:root {
    /* Brand Colors (OKLCH) */
    --brand-primary: oklch(50% 0.22 265);    /* Electric Blue */
    --brand-primary-hover: oklch(45% 0.2 265);

    --bg-main: oklch(100% 0 0);              /* White */
    --bg-surface: oklch(98% 0.01 265);       /* Off-white / light gray */
    --bg-surface-alt: oklch(95% 0.01 265);
    --bg-dark: oklch(20% 0.02 265);          /* Near black #141414 approx */

    --text-primary: oklch(20% 0.02 265);     /* Near black */
    --text-secondary: oklch(50% 0.02 265);   /* Subtitle gray */
    --text-inverse: oklch(100% 0 0);         /* White text */

    /* Typography */
    --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

    /* Spacing & Layout */
    --space-xs: 0.5rem;
    --space-sm: 1rem;
    --space-md: 2rem;
    --space-lg: 4rem;
    --space-xl: 8rem;

    --radius-sm: 6px;
    --radius-md: 12px;
    --radius-lg: 24px;
    --radius-pill: 9999px;

    /* Shadows */
    --shadow-soft: 0 4px 20px rgba(0, 0, 0, 0.05);
    --shadow-hover: 0 10px 30px rgba(0, 0, 0, 0.1);
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: var(--font-sans);
    color: var(--text-primary);
    background-color: var(--bg-main);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    overflow-x: hidden;
}

img {
    max-width: 100%;
    height: auto;
}

a {
    color: inherit;
    text-decoration: none;
    transition: color 0.2s ease;
}

a:hover {
    color: var(--brand-primary);
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    border: 0;
}

/* Layout */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 24px;
}

section {
    padding: var(--space-xl) 0;
}

.text-center { text-align: center; }
.mb-small { margin-bottom: var(--space-sm); }
.mb-medium { margin-bottom: var(--space-md); }
.mb-large { margin-bottom: var(--space-lg); }
.mb-xlarge { margin-bottom: var(--space-xl); }
.mt-small { margin-top: var(--space-sm); }
.mt-medium { margin-top: var(--space-md); }

.section-label {
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: var(--space-md);
}

.section-title {
    font-size: 2.5rem;
    font-weight: 700;
    letter-spacing: -0.02em;
    line-height: 1.1;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 14px 28px;
    border-radius: var(--radius-pill);
    font-weight: 500;
    font-size: 1rem;
    cursor: pointer;
    transition: all 0.2s ease;
    border: none;
}

.btn-sm {
    padding: 10px 20px;
    font-size: 0.875rem;
}

.btn-primary {
    background-color: var(--bg-dark);
    color: var(--text-inverse);
}

.btn-primary:hover {
    background-color: var(--brand-primary);
    color: var(--text-inverse);
    transform: translateY(-2px);
}

.btn-secondary {
    background-color: var(--bg-surface);
    color: var(--text-primary);
    border: 1px solid var(--bg-surface-alt);
}

.btn-secondary:hover {
    background-color: var(--bg-surface-alt);
}

/* Announcement Bar */
.announcement-bar {
    background-color: var(--bg-surface);
    text-align: center;
    padding: 12px 24px;
    font-size: 0.875rem;
    border-bottom: 1px solid var(--bg-surface-alt);
}

/* Header */
.header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 24px;
    padding-bottom: 24px;
}

.logo {
    font-size: 1.25rem;
    font-weight: 700;
    letter-spacing: -0.02em;
}

.main-nav {
    display: none;
}

@media (min-width: 768px) {
    .main-nav {
        display: flex;
        gap: 32px;
        font-weight: 500;
        font-size: 0.875rem;
    }
}

.auth-nav {
    display: flex;
    align-items: center;
    gap: 20px;
}

.nav-link {
    font-size: 0.875rem;
    font-weight: 500;
    display: none;
}

@media (min-width: 768px) {
    .nav-link {
        display: block;
    }
}

/* Hero Section */
.hero {
    padding: 100px 24px 60px;
    max-width: 900px;
}

.hero-title {
    font-size: 3.5rem;
    font-weight: 700;
    line-height: 1.1;
    letter-spacing: -0.03em;
    margin-bottom: 24px;
}

.hero-subtitle {
    font-size: 1.25rem;
    color: var(--text-secondary);
    max-width: 600px;
    margin: 0 auto 40px;
    line-height: 1.4;
}

.hero-ctas {
    display: flex;
    gap: 16px;
    justify-content: center;
    flex-wrap: wrap;
}

@media (min-width: 768px) {
    .hero-title {
        font-size: 4.5rem;
    }
}

/* Trusted By */
.trusted-by {
    padding: 40px 24px 80px;
}

.logo-row {
    display: flex;
    justify-content: center;
    gap: 40px;
    flex-wrap: wrap;
    opacity: 0.6;
    filter: grayscale(100%);
}

.brand-logo {
    font-weight: 700;
    font-size: 1.25rem;
    color: var(--text-secondary);
}

/* Stats Section */
.stats {
    background-color: var(--bg-surface);
    border-radius: var(--radius-lg);
    padding: 60px 24px;
    margin: 0 24px;
}

.stats-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 40px;
}

@media (min-width: 768px) {
    .stats-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

.stat-number {
    font-size: 3.5rem;
    font-weight: 700;
    letter-spacing: -0.03em;
    color: var(--brand-primary);
    line-height: 1;
    margin-bottom: 8px;
}

.stat-label {
    font-size: 1.125rem;
    font-weight: 500;
    color: var(--text-secondary);
}

/* Features - Search */
.tabs-container {
    display: flex;
    justify-content: center;
    gap: 8px;
    margin-bottom: 40px;
    flex-wrap: wrap;
}

.tab-btn {
    background: none;
    border: none;
    padding: 12px 24px;
    font-size: 1rem;
    font-weight: 500;
    color: var(--text-secondary);
    cursor: pointer;
    border-radius: var(--radius-pill);
    transition: all 0.2s ease;
}

.tab-btn:hover {
    color: var(--text-primary);
    background-color: var(--bg-surface);
}

.tab-btn.active {
    background-color: var(--bg-dark);
    color: var(--text-inverse);
}

.filters-wrapper {
    position: relative;
    margin-bottom: 40px;
}

.filters-wrapper::after {
    content: '';
    position: absolute;
    right: 0;
    top: 0;
    bottom: 0;
    width: 60px;
    background: linear-gradient(to right, rgba(255,255,255,0), var(--bg-main));
    pointer-events: none;
}

.filters-scroll {
    display: flex;
    gap: 12px;
    overflow-x: auto;
    padding-bottom: 16px;
    scrollbar-width: none; /* Firefox */
}

.filters-scroll::-webkit-scrollbar {
    display: none; /* Chrome */
}

.filter-pill {
    white-space: nowrap;
    background-color: var(--bg-surface);
    border: 1px solid transparent;
    padding: 8px 16px;
    border-radius: var(--radius-pill);
    font-size: 0.875rem;
    font-weight: 500;
    color: var(--text-secondary);
    cursor: pointer;
    transition: all 0.2s ease;
}

.filter-pill:hover {
    background-color: var(--bg-surface-alt);
    color: var(--text-primary);
}

.filter-pill.active {
    border-color: var(--bg-dark);
    color: var(--bg-dark);
    background-color: var(--bg-main);
}

.results-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 24px;
}

.result-card {
    background-color: var(--bg-surface);
    border-radius: var(--radius-md);
    padding: 12px;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.result-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-hover);
}

.skeleton-img {
    background-color: var(--bg-surface-alt);
    border-radius: var(--radius-sm);
    aspect-ratio: 9/19; /* Mobile app ratio approx */
    width: 100%;
}

/* Features - Flows */
.features-flows {
    background-color: var(--bg-surface);
    border-radius: var(--radius-lg);
    margin: var(--space-xl) 24px;
    padding: 80px 24px;
}

.toggle-container {
    display: flex;
    justify-content: center;
}

.toggle-switch {
    display: inline-flex;
    background-color: var(--bg-surface-alt);
    padding: 4px;
    border-radius: var(--radius-pill);
}

.toggle-btn {
    background: none;
    border: none;
    padding: 10px 24px;
    border-radius: var(--radius-pill);
    font-weight: 500;
    color: var(--text-secondary);
    cursor: pointer;
    transition: all 0.2s ease;
}

.toggle-btn.active {
    background-color: var(--bg-main);
    color: var(--text-primary);
    box-shadow: 0 2px 8px rgba(0,0,0,0.05);
}

.flow-preview-container {
    display: flex;
    justify-content: center;
}

.flow-view {
    display: none;
    width: 100%;
    max-width: 800px;
    animation: fadeIn 0.3s ease;
}

.flow-view.active {
    display: block;
}

.mockup-frame {
    background-color: var(--bg-main);
    border-radius: 20px;
    padding: 16px;
    box-shadow: var(--shadow-soft);
}

.mockup-screen {
    background-color: var(--bg-surface-alt);
    border-radius: 12px;
    aspect-ratio: 16/9;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    position: relative;
    color: var(--text-secondary);
    padding: 24px;
    text-align: center;
}

@media (max-width: 768px) {
    .mockup-screen {
        aspect-ratio: 4/3;
    }
}

.play-icon {
    font-size: 3rem;
    color: var(--brand-primary);
    margin-bottom: 16px;
}

.hotspot {
    position: absolute;
    width: 24px;
    height: 24px;
    background-color: var(--brand-primary);
    border-radius: 50%;
    opacity: 0.8;
    box-shadow: 0 0 0 4px rgba(0, 0, 0, 0.1);
    animation: pulse 2s infinite;
}

.hotspot:nth-child(1) { top: 30%; left: 40%; }
.hotspot.h-2 { top: 60%; left: 70%; animation-delay: 1s; }

/* Features - Tools */
.tools-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 32px;
    margin-top: 40px;
}

@media (min-width: 768px) {
    .tools-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

.tool-card {
    padding: 32px;
    background-color: var(--bg-main);
    border: 1px solid var(--bg-surface-alt);
    border-radius: var(--radius-md);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.tool-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-soft);
}

.tool-icon {
    width: 64px;
    height: 64px;
    background-color: var(--bg-surface);
    border-radius: var(--radius-md);
    margin: 0 auto 24px;
}

.tool-title {
    font-size: 1.25rem;
    font-weight: 600;
    margin-bottom: 12px;
}

.tool-desc {
    color: var(--text-secondary);
    font-size: 0.95rem;
}

/* Testimonials */
.testimonials {
    padding: 80px 0;
    background-color: var(--bg-surface);
    overflow: hidden;
}

.marquee-container {
    display: flex;
    flex-direction: column;
    gap: 24px;
}

.marquee-track {
    display: flex;
    gap: 24px;
    width: max-content;
    animation: scroll 40s linear infinite;
}

.marquee-track.track-reverse {
    animation: scroll-reverse 40s linear infinite;
}

.testimonial-card {
    background-color: var(--bg-main);
    padding: 32px;
    border-radius: var(--radius-md);
    width: 400px;
    box-shadow: var(--shadow-soft);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.quote {
    font-size: 1rem;
    line-height: 1.6;
    margin-bottom: 24px;
    color: var(--text-primary);
}

.author {
    display: flex;
    flex-direction: column;
}

.author strong {
    font-weight: 600;
}

.author span {
    font-size: 0.875rem;
    color: var(--text-secondary);
}

/* CTA Section */
.cta-section {
    padding: 120px 0 60px;
    overflow: hidden;
}

.cta-subtitle {
    font-size: 1.25rem;
    color: var(--text-secondary);
    max-width: 600px;
    margin: 0 auto 40px;
}

.brand-marquee-container {
    margin-top: 80px;
    display: flex;
    flex-direction: column;
    gap: 16px;
    opacity: 0.5;
}

.brand-track {
    display: flex;
    gap: 32px;
    width: max-content;
    animation: scroll 30s linear infinite;
}

.brand-track.track-reverse {
    animation: scroll-reverse 30s linear infinite;
}

.app-icon {
    background-color: var(--bg-surface);
    padding: 16px 32px;
    border-radius: var(--radius-pill);
    font-weight: 600;
    color: var(--text-secondary);
}

/* Footer */
.footer {
    background-color: var(--bg-surface);
    padding: 80px 0 40px;
    border-top: 1px solid var(--bg-surface-alt);
}

.footer-top {
    display: grid;
    grid-template-columns: 1fr;
    gap: 40px;
    margin-bottom: 60px;
}

@media (min-width: 768px) {
    .footer-top {
        grid-template-columns: 1fr 2fr;
    }
}

.footer-tagline {
    color: var(--text-secondary);
    margin-top: 16px;
    max-width: 250px;
}

.footer-links {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 40px;
}

@media (min-width: 768px) {
    .footer-links {
        grid-template-columns: repeat(3, 1fr);
    }
}

.link-column h4 {
    font-weight: 600;
    margin-bottom: 20px;
}

.link-column a {
    display: block;
    color: var(--text-secondary);
    margin-bottom: 12px;
    font-size: 0.95rem;
}

.link-column a:hover {
    color: var(--brand-primary);
}

.footer-bottom {
    display: flex;
    flex-direction: column;
    gap: 16px;
    border-top: 1px solid var(--bg-surface-alt);
    padding-top: 32px;
    color: var(--text-secondary);
    font-size: 0.875rem;
}

@media (min-width: 768px) {
    .footer-bottom {
        flex-direction: row;
        justify-content: space-between;
        align-items: center;
    }
}

.legal-links {
    display: flex;
    gap: 24px;
}

/* Animations */
@keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}

@keyframes scroll {
    0% { transform: translateX(0); }
    100% { transform: translateX(-50%); }
}

@keyframes scroll-reverse {
    0% { transform: translateX(-50%); }
    100% { transform: translateX(0); }
}

@keyframes pulse {
    0% { transform: scale(1); box-shadow: 0 0 0 0 rgba(0, 0, 0, 0.2); }
    70% { transform: scale(1.1); box-shadow: 0 0 0 10px rgba(0, 0, 0, 0); }
    100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(0, 0, 0, 0); }
}

document.addEventListener('DOMContentLoaded', () => {
    // 1. Stats Counter Animation
    const statsSection = document.querySelector('.stats');
    const statNumbers = document.querySelectorAll('.stat-number');
    let hasAnimated = false;

    const animateValue = (obj, start, end, duration) => {
        let startTimestamp = null;
        const step = (timestamp) => {
            if (!startTimestamp) startTimestamp = timestamp;
            const progress = Math.min((timestamp - startTimestamp) / duration, 1);
            // easeOutQuart
            const easeProgress = 1 - Math.pow(1 - progress, 4);
            const current = Math.floor(easeProgress * (end - start) + start);
            obj.innerHTML = new Intl.NumberFormat().format(current);
            if (progress < 1) {
                window.requestAnimationFrame(step);
            } else {
                obj.innerHTML = new Intl.NumberFormat().format(end);
            }
        };
        window.requestAnimationFrame(step);
    };

    const statsObserver = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting && !hasAnimated) {
                hasAnimated = true;
                statNumbers.forEach(stat => {
                    const target = parseInt(stat.getAttribute('data-target'), 10);
                    animateValue(stat, 0, target, 2000);
                });
            }
        });
    }, { threshold: 0.5 });

    if (statsSection) {
        statsObserver.observe(statsSection);
    }

    // 2. Search Tabs
    const tabBtns = document.querySelectorAll('.tab-btn');
    const searchResults = document.getElementById('search-results');

    const simulateLoading = () => {
        searchResults.style.opacity = '0.5';
        setTimeout(() => {
            searchResults.style.opacity = '1';
        }, 300);
    };

    tabBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            tabBtns.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            simulateLoading();
        });
    });

    // 3. Search Filters
    const filterPills = document.querySelectorAll('.filter-pill');
    filterPills.forEach(pill => {
        pill.addEventListener('click', () => {
            filterPills.forEach(p => p.classList.remove('active'));
            pill.classList.add('active');
            simulateLoading();
        });
    });

    // 4. Flows Toggle
    const flowToggles = document.querySelectorAll('.toggle-btn');
    const flowViews = document.querySelectorAll('.flow-view');

    flowToggles.forEach(btn => {
        btn.addEventListener('click', () => {
            const viewId = btn.getAttribute('data-view');

            flowToggles.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');

            flowViews.forEach(view => {
                view.classList.remove('active');
                if (view.id === `view-${viewId}`) {
                    view.classList.add('active');
                }
            });
        });
    });
});
